import random

def get_list(length):
    return [random.randint(0, 100) for _ in range(length)]

def sort_list(lst):
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if lst[i] > lst[j]:
                lst[i], lst[j] = lst[j], lst[i]
    return lst

def main():
    lst = get_list(10)
    print(sort_list(lst))

if __name__ == "__main__":
    main()

