import random
from pathlib import Path

def generate_code_snippets(num_snippets=50):
    snippets = []
    for i in range(num_snippets):
        snippet = "def func{}():\n  return {}\n\n".format(i, random.randint(0,100))
        snippets.append(snippet)

    return snippets

def save_code_snippets(snippets):
    for i, snippet in enumerate(snippets):
        filepath = Path(f"code_snippet_{i}.py")
        filepath.write_text(snippet)

if __name__ == "__main__":
    snippets = generate_code_snippets()
    save_code_snippets(snippets)

