import requests
import h11

def fetch_title(url):
    response = requests.get(url)
    connection = h11.Connection(our_role=h11.CLIENT)
    for data in connection.receive_data(response.content):
        if isinstance(data, h11.Response):
            title = data.headers.get_first("Title")
            return title
    return None

