from enum import IntEnum

class Sentiment(IntEnum):
    NEGATIVE = -1
    NEUTRAL = 0
    POSITIVE = 1

class Message:
    def __init__(self, body: str):
        self.body = body

    def get_sentiment(self) -> Sentiment:
        if "good" in self.body:
            return Sentiment.POSITIVE
        elif "bad" in self.body:
            return Sentiment.NEGATIVE
        else:
            return Sentiment.NEUTRAL

message = Message("I feel so good today!")
sentiment = message.get_sentiment()
print(sentiment)

