    print("Invited guests:")

    for guest in invited_guests:
        print('- ' + guest)

    print("\nWho would you like to invite?")

    new_guest = input()

    if new_guest in invited_guests:
        print(f"{new_guest} already invited, no need to re-invite.")
    else:
        invited_guests.append(new_guest)
        print(f"{new_guest} invited!")

    print("\nDinner Party Attendees:")
    for guest in invited_guests:
        print(guest)

