import tarfile
import os

def extract_and_chmod(tar_file, member):
    tar = tarfile.open(tar_file)
    tar.extract(member)

    path = os.path.join(member)

    for root, dirs, files in os.walk(path):
        for d in dirs:
            os.chmod(os.path.join(root, d), 0o777)
        for f in files:
            os.chmod(os.path.join(root, f), 0o777)

extract_and_chmod('files.tar', 'images/')

