import Dialogflow
import os
def create_intent(project_id, parent_session):
    client = Dialogflow.IntentsClient()
    parent = client.session_path(project_id, parent_session)

    training_phrases = []
    part = Dialogflow.Intent.Message.Text.TextPart(text='location')
    message = Dialogflow.Intent.Message.Text(text=[part])
    intent = Dialogflow.Intent(training_phrases=training_phrases, messages=[message])

    response = client.create_intent(parent, intent)
    return response.name

def get_domains(project_id):
    client = Dialogflow.AgentsClient()
    parent = client.agent_path(project_id)

    agent = client.get_agent(parent)
    return agent.default_language_code, agent.supported_language_codes

def get_location(domain):
    if domain == 'trip':
        return Dialogflow.Intent.Message.Text.TextPart(text='location')
    else:
        return Dialogflow.Intent.Message.Text.TextPart(text='city')

def create_trip_booking_agent(project_id):
    domain = get_domains(project_id)[0]
    location = get_location(domain)

    parent_session = os.environ['DIALOGFLOW_SESSION']
    intent_name = create_intent(project_id, parent_session)

    intent = Dialogflow.Intent(training_phrases=[], messages=[Dialogflow.Intent.Message.Text(text=[location])])
    response = client.create_intent(parent_session, intent)

