import hashlib
import resources

def generate_user_password_salt(username):
    return hashlib.sha256(resources.USER_DATA[username]['email'].encode()).hexdigest()

def verify_user_password(username, password):
    password_hash = hashlib.sha256(password.encode()).hexdigest()

    expected_password_hash = resources.USER_DATA[username]['password']

    salt = generate_user_password_salt(username)

    return password_hash == expected_password_hash

