import os
import shutil

def organize_photos():
    for f in os.listdir('photos'):
        if f.endswith('.jpg'):
            shutil.move('photos/' + f, 'organized/' + f)
    os.chdir('organized')
    for f in os.listdir('organized'):
        if f.startswith('hawaii'):
            os.rename(f, 'vacation_' + f)
        elif f.startswith('stewie'):
            os.rename(f, 'baby_stewie_' + f)

    os.chmod('organized', 0o777)

organize_photos()

